(function() {
        const privacyConsent = window.PrivacyConsent;
        if (!privacyConsent) return;

        const codeGroups = {
            functional: {
                head: "\n",
                bodyfront: "\n",
                bodyend: "\n",
            },
            marketing: {
                head: "<!-- Google tag (gtag.js) -->\r\n<script async src=\"https:\/\/www.googletagmanager.com\/gtag\/js?id=G-M113HD0BRJ\" nonce=\"35b333ded68a99f689b77921474a6ea0\"><\/script>\r\n<script nonce=\"35b333ded68a99f689b77921474a6ea0\">\r\n  window.dataLayer = window.dataLayer || [];\r\n  function gtag(){dataLayer.push(arguments);}\r\n  gtag('js', new Date());\r\n\r\n  gtag('config', 'G-M113HD0BRJ');\r\n<\/script>\n",
                bodyfront: "\n",
                bodyend: "\n",
            },
        };

        privacyConsent.syncCheckboxes({
            functional: '#cookie_functional',
            marketing: '#cookie_marketing',
        });

        $('#modulePrivacy .topBox .subtitle').on('click', function(e) {
            $(this).parents('.topBox').stop(false, false).toggleClass('open');
            $(this).parents('.topBox').siblings('.text').stop(false, false).slideToggle(300);
        });

        function removePrivacyElement() {
            $('body').removeClass('overflow');
            $('#modulePrivacy, .moduleMask').removeClass('show');
            $('.privacyArea').addClass('check');

            setTimeout(function() {
                $('#modulePrivacy, .privacyArea').remove();
            }, 1000);
        }

        if(navigator.cookieEnabled) {

            $('#modulePrivacy .privacyTrigger, .privacyArea .privacyTrigger').on('click', function(e) {
                e.preventDefault();

                const savedBefore = privacyConsent.get();
                let privacyJson = {
                    necessary: true,
                    functional: true,
                    marketing: true
                };

                if($(this).hasClass('acceptCustom')) {
                    privacyJson = privacyConsent.readCheckboxes({
                        functional: '#cookie_functional',
                        marketing: '#cookie_marketing',
                    });
                }

                const saved = privacyConsent.save(privacyJson);
                if (!saved) return;

                if (savedBefore !== null) {
                    location.reload();
                    return;
                }

                privacyConsent.injectGranted(codeGroups, saved);

                removePrivacyElement();
            });
        } else {
            $('#modulePrivacy .btn a, .privacyArea .btn a.acceptAll').on('click', function(e) {
                e.preventDefault();
                removePrivacyElement();
            });
        }
    })();

