            // 2. 更新洽詢與比較按鈕狀態
            updateInquiryCompareButtons(selectedWattageId);

            // 3. 連動規格表頁籤中的瓦數按鈕樣式
            $('.wattageTitle').removeClass('current');
            $('.wattageTitle[data-id="' + selectedWattageId + '"]').addClass('current');

            // 4. 切換規格表內容 (只顯示當前瓦數對應的那一欄)
            $('.spec_col').hide();
            $('.spec_col_' + selectedWattageId).show();

            // 5. 切換該瓦數的內容說明
            $('.wattageExpBox').hide();
            $('.wattageExp_' + selectedWattageId).show();

            // 6. 切換該瓦數的價格說明
            $('.priceNoteBox').hide();
            $('.priceNote_' + selectedWattageId).show();

            // 7. 切換該瓦數的線材清單
            $('.wattageCable').hide();
            $('.wattageCable_' + selectedWattageId).show();

            // 8. 切換該瓦數的下載連結
            updateDownloadLink(selectedWattageId);
        });

        $('.wattageBox .rwdContent').text($('.wattageTitle').first().text());

        $('.wattageBox .rwdContent').on('click', function(){
            $(this).closest('.wattageBox').find('.wattageTitle').toggleClass('show');
        });

        // 點擊規格表上方的瓦數按鈕，同步切換下拉選單
        $(document).on('click', '.wattageTitle', function(){
            var id = $(this).data('id');
            $('.wattageSelect').val(id).trigger('change');

            $('.wattageTitle').removeClass('show');

            let text = $(this).text();
            $('.rwdContent').text(text);

            // 如果是在規格表頁籤，點擊時捲動到上方 introBox 比較好觀察變化 (選用)
            // $('html, body').animate({ scrollTop: $('.insIntroBox').offset().top - 100 }, 500);
        });

        // 依目前瓦數更新下載連結
        function updateDownloadLink(wattageId) {
            var $link = $('#downloadTabLink');
            if (!$link.length) return;

            var map = $link.data('download-map');
            if (typeof map === 'string') {
                try {
                    map = JSON.parse(map);
                } catch (e) {
                    map = {};
                }
            }

            wattageId = String(wattageId);
            var url = map && map[wattageId] ? map[wattageId] : '';

            if (url) {
                $link.attr('href', url);
                $link.closest('.tabDownloadItem').show();
            } else {
                $link.closest('.tabDownloadItem').hide();
            }
        }

        // 更新按鈕狀態
        function updateInquiryCompareButtons(id) {
            id = String(id);
            if (typeof currentInquiryList !== 'undefined') {
                if (currentInquiryList.indexOf(id) > -1) {
                    $('#mainQuoteBtn').addClass('current').find('.btnText').text(langArr.removeInquiry);
                } else {
                    $('#mainQuoteBtn').removeClass('current').find('.btnText').text(langArr.addInquiry);
                }
            }

            if (typeof currentCompareList !== 'undefined') {
                if (currentCompareList.indexOf(id) > -1) {
                    $('#mainCompareBtn').addClass('current').find('.btnText').text(langArr.removeCompare);
                } else {
                    $('#mainCompareBtn').removeClass('current').find('.btnText').text(langArr.addCompare);
                }
            }

            if (typeof currentPreorderList !== 'undefined') {
                $('#mainPreOrderBtn').attr('data-pr-id', id);

                if (currentPreorderList.indexOf(id) > -1) {
                    $('#mainPreOrderBtn').addClass('current').find('.btnText').text(langArr.removePreOrder);
                } else {
                    $('#mainPreOrderBtn').removeClass('current').find('.btnText').text(langArr.addPreOrder);
                }
            }
        }

        // 洽詢按鈕點擊
        $(document).on('click', '#mainQuoteBtn', function(e){
            e.preventDefault();
            var id = String($('.wattageSelect').val());
            if(!id) return;

            addInquiry(id);

            // 更新本地狀態：如果已存在則移除，否則加入
            var index = currentInquiryList.indexOf(id);
            if (index > -1) {
                currentInquiryList.splice(index, 1);
            } else {
                currentInquiryList.push(id);
            }
            updateInquiryCompareButtons(id);
        });

        // 比較按鈕點擊
        $(document).on('click', '#mainCompareBtn', function(e){
            e.preventDefault();
            var id = String($('.wattageSelect').val());
            if(!id) return;

            compare(id);

            // 更新本地狀態：如果已存在則移除，否則加入
            var index = currentCompareList.indexOf(id);
            if (index > -1) {
                currentCompareList.splice(index, 1);
            } else {
                currentCompareList.push(id);
            }
            updateInquiryCompareButtons(id);
        });

        // 預購按鈕點擊
        $(document).on('click', '#mainPreOrderBtn', function(e){
            e.preventDefault();
            var id = String($('.wattageSelect').val());
            if(!id) return;

            addpreorder(id);

            // 更新本地狀態：如果已存在則移除，否則加入
            var index = currentPreorderList.indexOf(id);
            if (index > -1) {
                currentPreorderList.splice(index, 1);
            } else {
                currentPreorderList.push(id);
            }
            updateInquiryCompareButtons(id);
        });

        const homeClassAjax = new classAjax();
        const albumEvent = new albumTriggerObj();

        if($('.colorList button').length < 1) {
            albumEvent.initial();
        }

        // 顏色點擊切換相簿
        $(document).on('click', '.colorList button', function(){
            let current = $(this);
            let currentMblink = current.data('id');

            // 如果已經是當前選中，就不重複執行
            if(current.hasClass('current')) {
                return false;
            }

            // 防止記憶體洩漏：更新 HTML 前先銷毀舊的 Slick 實例
            try {
                if ($('.albumListMain').hasClass('slick-initialized')) {
                    $('.albumListMain').slick('unslick');
                }
                if ($('.albumListNav').hasClass('slick-initialized')) {
                    $('.albumListNav').slick('unslick');
                }
            } catch(e) {}

            let callBack = function() {
                current.addClass('current');
                current.siblings().removeClass('current');

                // 建立全新實例以獲取最新的 DOM 元素並初始化
                const newAlbumEvent = new albumTriggerObj();
                newAlbumEvent.initial();

                $('.titan').lightGallery({
                    actualSize: false,
                    download: false,
                    hash: false,
                    share: false,
                    // 影片自動撥放設定
                    autoplayFirstVideo: false,
                    tumbnails: false,
                    youtubePlayerParams: {
                        rel: 0,
                        controls: 0
                    },
                });
            }

            homeClassAjax.get('.albumBox', 'products', currentMblink, 3, callBack);
        });

        // 一進入頁面時，自動先選擇 select 的第一筆 option 並觸發 change
        var $wattageSelect = $('.wattageSelect');
        var firstVal = $wattageSelect.find('option:first').val();
        if(firstVal) {
            $wattageSelect.val(firstVal).trigger('change');
        }

        //tab 
		$('.tabContent .tabContentItem').eq(0).show();
		$('.tab [data-js="tab"]') .eq(0).find('a').addClass('current');
        $('.tab [data-js="tab"]') .find('a').on('click', function(){
            var obj = $(this).attr('href');
            if (/^https?:\/\//i.test(obj)) {
                return true;
            }
			$(this).addClass('current').parent('[data-js="tab"]').siblings().find('.current').removeClass('current');
			$(obj).fadeIn().siblings().hide();
			return false;
		});
	});
